import os
from typing import Optional
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandTimeout, MolerException  # type: ignore
from taf.ul.sc.epcsim import Egate  # type: ignore
from taf.ul.sc.epcsim import Workstation  # type: ignore
from taf.ul.sc.perf.devices.core.core import Core
from taf.ul.sc.perf.devices.core.calculate_burst import CalculateBurst
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console
from taf.ul.sc.perf.util.recovery_observer_manager import RecoveryObserverManager
from taf.ul.sc.perf.testline.device_helpers import get_device_number


class EpcSim(Core):

    def __init__(self,
                 egate: Egate,
                 workstation: Optional[Workstation] = None,
                 ):

        self.egate = egate
        self.ws = workstation
        self.name = self.egate.name
        self.ws_name = self.ws.name if self.ws else self.egate.ws_name
        self._recovery = None

    @log_function_status_to_console(msg="Change configuration file", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def change_configuration_file(self, config_file, required_files=None):
        self.ws.upload_configuration(config_file=config_file, required_files=required_files, raise_exception=True)
        if self.egate.get_state()['STATE'] in ['CONFIGURED', 'ACTIVE', 'ACTIVATING', 'STARTING']:
            self.egate.reset()
        self.egate.configure(config_file=os.path.join('config', os.path.basename(config_file)))
        self._wait_on_active_state()

    @log_function_status_to_console(msg="Configure console prints", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def configure_console_prints(self, params=None):
        self.egate.configure_rfm_filter(options=params)

    def restart_configuration(self):
        if self.egate.get_state()['STATE'] in ['ACTIVE', 'ACTIVATING']:
            self.egate.stop()
        self.egate.start()

    def _wait_on_active_state(self, step=10, timeout=240):

        while timeout:
            try:
                state = self.egate.get_state()['STATE']
            except CommandTimeout:
                state = None
            if state == 'CONFIGURED':
                self.egate.start()
            elif state in ['ACTIVE', 'ACTIVATING']:
                return True

            MolerTest.sleep(step)
            timeout = timeout - step

    @log_function_status_to_console(msg="Start PAGING", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_paging(self, params):
        """
        Params for start fake paging
        Eg:
            params:
                BTS0:
                    imsi:         '440:80:8800'
                    imsi_num:     100
                    imsi_pct:     1
                    burst_size:   20
                    paging_rate:  80
                BTS1:
                    imsi:         '440:80:8800'
                    imsi_num:     100
                    imsi_pct:     1
                    burst_size:   20
                    burst_period: 250
        :param params:
        :return:
        """
        for bts_name in params:
            bts_id = get_device_number(bts_name) + 1
            bts_params = params[bts_name]
            if bts_params.get('paging_rate', None):
                paging_rate = bts_params.pop('paging_rate')
                burst_params = self._get_paging_burst_params(paging_rate=paging_rate,
                                                             burst_size=bts_params['burst_size'])
                bts_params['burst_size'] = burst_params[0]
                bts_params['burst_period'] = burst_params[1]

            self.egate.start_fake_paging(enbs=bts_id, options=bts_params)

    @log_function_status_to_console(msg="Stop PAGING", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_paging(self, bts_names):
        """

        :param bts_names: list of bts_names eg ['BTS0', 'BTS1']
        :return:
        """
        for bts_name in bts_names:
            bts_id = get_device_number(bts_name) + 1
            self.egate.stop_fake_paging(enbs=bts_id)

    @log_function_status_to_console(msg="Collect configuration", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_configuration(self, log_dir, config_file_dir=None):
        """
        Collect configuration files used in the test.
        :param log_dir: local dir path.
        :param config_file_dir: config file directory.
        :return:
        """
        self.ws.get_config_file(config_log_dir=log_dir, config_dir_to_download=config_file_dir)

    @staticmethod
    def _get_paging_burst_params(paging_rate, burst_size=20):
        cp = CalculateBurst(paging_rate=paging_rate, burst_size=burst_size)
        cp.calculate_burst_params()

        return cp.burst_size, cp.burst_period

    @log_function_status_to_console(msg="Get PGW and SGW stats.", log_hierarchy=2, add_name_prefix=True,
                                    ignore_exception=True)
    @log_debug_function_info()
    def get_sgw_and_pgw_stats(self):
        self._execute_cmd_without_error_status(cmd_to_execute=self.egate.get_sgw_stats, cmd_params={'sgw_id': 'all'},
                                               warning_msg='Cannot get SGW stats')
        self._execute_cmd_without_error_status(cmd_to_execute=self.egate.get_pgw_stats, cmd_params={'pgw_id': 'all'},
                                               warning_msg='Cannot get PGW stats')

    @log_function_status_to_console(msg="Clear PGW and SGW stats.", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def clear_sgw_and_pgw_stats(self):
        self._execute_cmd_without_error_status(cmd_to_execute=self.egate.clear_sgw_stats, cmd_params={'sgw_id': 'all'},
                                               warning_msg='Cannot clear SGW stats')
        self._execute_cmd_without_error_status(cmd_to_execute=self.egate.clear_pgw_stats, cmd_params={'pgw_id': 'all'},
                                               warning_msg='Cannot clear PGW stats')

    def restart(self, edaemon_port=10000):
        # TODO Add support for many daemons:
        #      few daemons on the same virtual machine(EPCSIM_WS)
        #      daemons could be run on separate virtual machinesl

        self.egate.device.goto_state("UNIX_LOCAL")
        self.ws.kill_and_start_epcsim(edaemon_port=edaemon_port, egate_port=self.egate.port)
        self.egate.connect()

    @log_function_status_to_console(msg="Start recovery observers", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_recovery_observers(self, action='test_recovery', recovery_params=None, before=None, after=None):
        self._recovery = RecoveryObserverManager(device=self.egate.device,
                                                 events=[{'event_name': 'change_state',
                                                          'event_params': {'egate_state': 'configured'}}])

        self._recovery.start_recovery_observers(action, recovery_params, before, after)

    @log_function_status_to_console(msg="Stop recovery observers", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_recovery_observers(self):
        self._recovery.stop_recovery_observers()

    def get_version(self):
        core_info = {'sw_version': self.egate.get_version()}
        return core_info

    @staticmethod
    def _execute_cmd_without_error_status(cmd_to_execute, warning_msg, cmd_params=None):
        if cmd_params is None:
            cmd_params = {}

        try:
            cmd_to_execute(**cmd_params)
        except MolerException:
            MolerTest.warning(warning_msg)
